/**
 * Research figure catalogue (科研绘图) for the 扩展 → 模板 page.
 *
 * GENERATED FILE — do not edit by hand. Run `pnpm run figures:catalog`.
 *
 * Two families:
 *
 *  - MathModel figure templates extracted from the installed product, in the
 *    `mathmodel-figure-templates` skill. Ids, titles, categories and layout notes are
 *    the product's own metadata.
 *  - Templates written for this project, under `math_figure/assets/templates/`.
 *
 * Previews are rendered here, not copied from the product:
 *   `pnpm run figures:mathmodel` (MathModel set) and `pnpm run figures:build` (ours).
 */

export type FigureCategory =
  | 'combination'
  | 'distribution'
  | 'flowchart'
  | 'machine-learning'
  | 'model-evaluation'
  | 'spatial'
  | 'ordination'
  | 'composition'
  | 'three-dimensional'
  | 'surface'
  | 'association'
  | 'other'
  | 'attribution'
  | 'feature-report'
  | 'time-series'
  | 'prediction'
;

export interface FigureEntry {
  id: string;
  title: string;
  category: FigureCategory;
  description: string;
  /** Skill that owns the template (both families live in their own skill). */
  skill: 'math-figure' | 'mathmodel-figure-templates';
  /** Path of the script, relative to that skill directory. */
  script: string;
  /** Preview key under src/assets/figures/, empty when none was rendered. */
  preview: string;
  /** Python packages beyond matplotlib the template imports. */
  dependencies: string[];
  available: boolean;
}

