/** Preview images, resolved from the renderer asset folder at build time. */
const PREVIEWS = import.meta.glob<string>('../assets/figures/**/*.png', {
  eager: true,
  import: 'default',
});

/** Thumbnail URL for a catalogue entry, empty string when none was rendered. */
export function figurePreview(entry: FigureEntry): string {
  return entry.preview ? (PREVIEWS[`../assets/figures/${entry.preview}.png`] ?? '') : '';
}

export const AVAILABLE_FIGURE_COUNT = FIGURE_CATALOG.filter((e) => e.available).length;
